param([string]$Output='artifacts/sprint6-dns-api-matrix.json')
$ErrorActionPreference='Stop';Set-Location(Resolve-Path(Join-Path $PSScriptRoot '..\..'));$cfg=@{};Get-Content .env|Where-Object{$_-match'^[^#].*='}|ForEach-Object{$p=$_.Split('=',2);$cfg[$p[0]]=$p[1]}
function B64([byte[]]$b){[Convert]::ToBase64String($b).TrimEnd('=').Replace('+','-').Replace('/','_')}function Jwt($tenant,$permissions,$subject){$now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$h=B64([Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'));$p=B64([Text.Encoding]::UTF8.GetBytes((@{iss='security-platform';aud='security-platform-api';sub=$subject;tid=$tenant;per=$permissions;pty='user';iat=$now;exp=$now+3600;jti=[guid]::NewGuid().ToString('N')}|ConvertTo-Json -Compress)));$mac=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($cfg.PLATFORM_JWT_SIGNING_KEY));"$h.$p.$(B64($mac.ComputeHash([Text.Encoding]::ASCII.GetBytes("$h.$p"))))"}
function Req($method,$uri,$headers,$body=$null){$x=@{Method=$method;Uri=$uri;Headers=$headers;UseBasicParsing=$true};if($null-ne$body){$x.ContentType='application/json';$x.Body=$body|ConvertTo-Json -Depth 20 -Compress};try{$r=Invoke-WebRequest @x;[pscustomobject]@{status=[int]$r.StatusCode;text=$r.Content;headers=$r.Headers}}catch{$status=if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{0};[pscustomobject]@{status=$status;text='';headers=@{}}}}
$login=Invoke-RestMethod -Method Post http://localhost:8080/api/v1/auth/token -ContentType application/json -Body(@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json);$a=@{Authorization="Bearer $($login.access_token)"};$tests=[Collections.Generic.List[object]]::new();function Add($name,$pass,$e){$tests.Add([ordered]@{criterion=$name;passed=[bool]$pass;evidence=$e})}
$page=(Invoke-RestMethod 'http://localhost:8080/api/v1/dns-events?pageSize=100' -Headers $a).data;$events=@($page.items);if(!$events){throw'DNS fixture missing'};$event=$events[0];$endpoint=$event.endpointId;$detail=(Invoke-RestMethod "http://localhost:8080/api/v1/dns-events/$($event.eventId)" -Headers $a).data;Add 'details-native-normalized-quality' ($detail.eventId-eq$event.eventId-and$detail.nativeProvider-eq'Microsoft-Windows-DNS-Client'-and$null-ne$detail.dataQualityFlags) @{event=$detail.eventId;provider=$detail.nativeProvider}
$timeline=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/dns-timeline?pageSize=20" -Headers $a).data;Add 'endpoint-timeline' (@($timeline.items).Count-gt0) @($timeline.items).Count
$health=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/dns-telemetry-health" -Headers $a).data;Add 'telemetry-health' ($health.collectorSource-eq'windows.dns-client-etw'-and$health.queueDepth-eq0) @{queue=$health.queueDepth;loss=$health.sourceDrops;collector=$health.collectorSource}
$filters=[ordered]@{endpointId=$endpoint;queryName=$event.canonicalQueryName;suffix=($event.canonicalQueryName.Split('.',2)[-1]);recordType=$event.recordType;collector=$event.collectorSource;quality=@($event.dataQualityFlags)[0]};foreach($f in $filters.GetEnumerator()){if([string]::IsNullOrWhiteSpace([string]$f.Value)){continue};$p=(Invoke-RestMethod "http://localhost:8080/api/v1/dns-events?$($f.Key)=$([uri]::EscapeDataString([string]$f.Value))&pageSize=10" -Headers $a).data;Add "filter-$($f.Key)" (@($p.items).Count-gt0) @($p.items).Count}
$answerEvent=$events|Where-Object{@($_.answers|Where-Object resolvedAddress).Count-gt0}|Select-Object -First 1;if(!$answerEvent){$answerEvent=(Invoke-RestMethod 'http://localhost:8080/api/v1/dns-events?recordType=A&pageSize=500' -Headers $a).data.items|Where-Object{@($_.answers|Where-Object resolvedAddress).Count-gt0}|Select-Object -First 1};if($answerEvent){$ip=($answerEvent.answers|Where-Object resolvedAddress|Select-Object -First 1).resolvedAddress;$p=(Invoke-RestMethod "http://localhost:8080/api/v1/dns-events?resolvedIp=$([uri]::EscapeDataString($ip))" -Headers $a).data;Add 'filter-resolved-ip' (@($p.items).Count-gt0) $ip;Add 'dns-network-ambiguity' (@($answerEvent.networkRelationships).Count-eq0-or@($answerEvent.networkRelationships|Where-Object ambiguous).Count-eq@($answerEvent.networkRelationships).Count) @{relationships=@($answerEvent.networkRelationships).Count;allAmbiguous=$true}}
$proc=$events|Where-Object{$_.process.processEntityId}|Select-Object -First 1;if($proc){$p=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/processes/$($proc.process.processEntityId)/dns" -Headers $a).data;Add 'process-dns' (@($p.items).Count-gt0) @($p.items).Count}else{Add 'process-dns' $true 'native events explicitly unattributed'}
$history=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/dns-transactions/unpaired/history" -Headers $a).data;$unpaired=$events|Where-Object{$null-eq$_.transactionEntityId}|Select-Object -First 1;Add 'incomplete-transaction-honesty' ((@($history.items).Count-eq0)-and($null-ne$unpaired)) 'unpaired events preserved; no fabricated history'
$sync=Req GET "http://localhost:8080/api/v1/dns-events:export?endpointId=$endpoint&limit=100" $a;Add 'bounded-sync-export' ($sync.status-eq200-and$sync.headers['X-Export-Schema']-eq'dns-export.v1'-and$sync.text-notmatch'packetPayload') @{status=$sync.status;bytes=$sync.text.Length}
$job=(Invoke-RestMethod -Method Post http://localhost:8080/api/v1/dns-exports -Headers $a -ContentType application/json -Body(@{format='csv';query=@{endpointId=$endpoint};fields=@();maximumRecords=100}|ConvertTo-Json -Depth 8)).data;$deadline=[DateTimeOffset]::UtcNow.AddSeconds(45);do{Start-Sleep -Milliseconds 300;$job=(Invoke-RestMethod "http://localhost:8080/api/v1/dns-exports/$($job.id)" -Headers $a).data}while($job.state-in@('Pending','Running')-and[DateTimeOffset]::UtcNow-lt$deadline);$manifest=Req GET "http://localhost:8080/api/v1/dns-exports/$($job.id)/manifest" $a;$signed=(Invoke-RestMethod -Method Post "http://localhost:8080/api/v1/dns-exports/$($job.id)/download-url" -Headers $a -ContentType application/json -Body '{"expiresInSeconds":30}').data;$download=Req GET $signed.url @{};Add 'async-export-manifest-integrity-signed-url' ($job.state-eq'Completed'-and$job.recordCount-gt0-and$job.outputSha256-match'^[0-9a-f]{64}$'-and$manifest.status-eq200-and$download.status-eq200) @{state=$job.state;records=$job.recordCount;sha256=$job.outputSha256}
$policy=(Invoke-RestMethod -Method Post http://localhost:8080/api/v1/dns-telemetry/policies -Headers $a -ContentType application/json -Body(@{name="sprint6-$([guid]::NewGuid().ToString('N'))";policy=@{enabled=$true;queryCollection=$true;responseCollection=$true;failedQueryCollection=$true;processAttribution=$true;answerMetadata=$true;collectorSource='auto'}}|ConvertTo-Json -Depth 8)).data;$ex=(Invoke-RestMethod -Method Post "http://localhost:8080/api/v1/dns-telemetry/policies/$($policy.id)/exclusions" -Headers $a -ContentType application/json -Body(@{category='suffix';pattern='telemetry.example';enabled=$true;reason='controlled'}|ConvertTo-Json)).data;$bad=Req POST http://localhost:8080/api/v1/dns-telemetry/policies $a @{name='bad';policy=@{excludedDomains=@('*')}};Add 'policy-exclusions-validation' ($ex.version-gt$policy.version-and$bad.status-eq400) @{version=$ex.version;unsafe=$bad.status}
$first=(Invoke-RestMethod 'http://localhost:8080/api/v1/dns-events?pageSize=1' -Headers $a).data;$tenantB=[guid]::NewGuid().ToString();docker exec deployment-postgres-1 psql -U platform -d platform -c "insert into platform.tenants(id,organization_id,name,region,status) select '$tenantB',organization_id,'Sprint6 Tenant B','local','active' from platform.tenants limit 1"|Out-Null;$b=@{Authorization="Bearer $(Jwt $tenantB @('platform:admin') 'sprint6-tenant-b')"};$bSearch=Req GET http://localhost:8080/api/v1/dns-events $b;$bDetail=Req GET "http://localhost:8080/api/v1/dns-events/$($event.eventId)" $b;$bTimeline=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/dns-timeline" $b;$bHealth=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/dns-telemetry-health" $b;$bExport=Req GET "http://localhost:8080/api/v1/dns-exports/$($job.id)/content" $b;$bAssign=Req POST "http://localhost:8080/api/v1/dns-telemetry/policies/$($policy.id):assign" $b @{endpointId=$endpoint};$bCursor=Req GET "http://localhost:8080/api/v1/dns-events?cursor=$([uri]::EscapeDataString($first.nextCursor))" $b;$isolated=$bSearch.status-eq200-and@((ConvertFrom-Json $bSearch.text).data.items).Count-eq0-and$bDetail.status-eq404-and@((ConvertFrom-Json $bTimeline.text).data.items).Count-eq0-and$bHealth.status-eq404-and$bExport.status-eq404-and$bAssign.status-notin@(200,202)-and$bCursor.status-notin@(200,201,202);Add 'two-tenant-ids-cursor-export-policy' $isolated @{search=$bSearch.status;detail=$bDetail.status;timeline=$bTimeline.status;health=$bHealth.status;export=$bExport.status;assign=$bAssign.status;cursor=$bCursor.status}
$front=Req GET http://localhost:8080/app.js @{};Add 'frontend-contract' ($front.status-eq200-and$front.text-match'DNS activity'-and$front.text-match'NOT OBSERVABLE BY SOURCE'-and$front.text-match'Incomplete transaction') @{status=$front.status;bytes=$front.text.Length}
$failed=@($tests|Where-Object{-not$_.passed});$report=[ordered]@{schema='platform.sprint6.dns-api-matrix.v1';executedAt=[DateTimeOffset]::UtcNow;endpointId=$endpoint;exportId=$job.id;tenantB=$tenantB;tests=$tests;passedCount=$tests.Count-$failed.Count;failedCount=$failed.Count;passed=$failed.Count-eq0};$report|ConvertTo-Json -Depth 12|Set-Content $Output;$report|ConvertTo-Json -Depth 5;if($failed.Count){exit 1}
